import{_ as e}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as t,o as s,c as n,a3 as r}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"G6, ONE","description":"","frontmatter":{"source_hash":"5b747a77e0","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/install/g6.md","filePath":"it/install/g6.md"}'),l={name:"it/install/g6.md"};function c(m,o,d,p,u,v){return s(),n("div",null,[...o[0]||(o[0]=[r('<div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Dex</p></div><h3 id="g6-or-dexcom-one" tabindex="-1">G6 o Dexcom ONE <a class="header-anchor" href="#g6-or-dexcom-one" aria-label="Permalink to &quot;G6 o Dexcom ONE {#g6-or-dexcom-one}&quot;">​</a></h3><p>Questa pagina descrive come configurare con xDrip un trasmettitore e un sensore Dexcom G6 o Dexcom ONE. Dal punto di vista di xDrip i due sono lo stesso dispositivo (stesso hardware del trasmettitore, stesso protocollo BLE): tutti i passaggi qui sotto valgono per entrambi.</p><p>La documentazione di riferimento è <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">qui</a>.</p><p>Per G7 o ONE+, consulta invece la <a href="./g7.html">pagina dedicata a G7 e ONE+</a>.</p><h4 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h4><ul><li>Verifica che la configurazione del telefono rispetti i <a href="./prerequisites.html">prerequisiti</a> di xDrip.</li><li>Di norma non puoi avere contemporaneamente xDrip e l&#39;app Dexcom che ricevono i dati direttamente dallo stesso trasmettitore. Disinstalla l&#39;app Dexcom se vuoi che xDrip sia il collector. Se devi continuare a usare l&#39;app Dexcom, solo lei può essere il collector: usa allora xDrip come follower di un&#39;<a href="./companion.html">app compagno</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">Non abbinare dalle impostazioni Bluetooth di Android</p><p>Non provare mai ad abbinare il trasmettitore dalla pagina delle impostazioni Bluetooth di Android: lascia che sia xDrip ad avviare la richiesta di abbinamento e accettala quando ti viene chiesto. Il trasmettitore trasmette solo per qualche secondo ogni 5 minuti, quindi non stupirti se la maggior parte del tempo Android non lo elenca tra i dispositivi abbinati.</p></div><p>La pagina <a href="./../troubleshoot/systemstatus.html">Stato del sistema</a> (menu in alto a sinistra) ha una sezione &quot;Dex Status&quot; con i parametri che ti serviranno in tutta questa pagina: ID del trasmettitore, tempo trascorso dall&#39;ultima connessione, versione del firmware, giorni del trasmettitore e tensioni della batteria.</p><h4 id="dexcom-device-compatibility" tabindex="-1">Compatibilità con i dispositivi Dexcom <a class="header-anchor" href="#dexcom-device-compatibility" aria-label="Permalink to &quot;Compatibilità con i dispositivi Dexcom {#dexcom-device-compatibility}&quot;">​</a></h4><ul><li><strong>Microinfusore t:slim</strong>: avvia il sensore G6 <strong>sul microinfusore</strong>, non in xDrip, e non avviarlo anche in xDrip. Dopo il periodo di riscaldamento xDrip rileverà e riprenderà da solo la sessione in corso (tocca <strong>Riavvia Collector</strong> nella pagina Classic Status se non lo fa). Non serve nemmeno inserire il codice di calibrazione in xDrip: ne ha bisogno solo il trasmettitore.</li><li><strong>Ricevitore Dexcom</strong>: puoi usarlo insieme a xDrip, ma evita di inviare comandi duplicati di avvio/arresto/calibrazione da entrambi. Se devi usare il ricevitore, avvia il sensore lì e lascia che xDrip riprenda la sessione dopo il riscaldamento. Non fermare il sensore da xDrip pensando che riguardi solo xDrip: ferma l&#39;intera sessione sul trasmettitore.</li><li><strong>Non puoi</strong> usare contemporaneamente un microinfusore t:slim e un ricevitore Dexcom (usano lo stesso slot del trasmettitore), né usare xDrip e l&#39;app Dexcom insieme, a meno che l&#39;app Dexcom non sia l&#39;unica a ricevere i dati: in quel caso xDrip può seguirla tramite <a href="./companion.html">Companion App</a>.</li></ul><h4 id="before-you-start" tabindex="-1">Prima di iniziare <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Prima di iniziare {#before-you-start}&quot;">​</a></h4><p>Per iniziare ti servono un trasmettitore e un sensore.</p><div class="info custom-block"><p class="custom-block-title">Scadenza del trasmettitore</p><p>Controlla le due date stampate sulla scatola del trasmettitore: la data di fabbricazione e una data Ship-By o Use-By. Non accettare un trasmettitore la cui data Ship-By/Use-By sia già passata. Non togliere il trasmettitore dalla scatola e non toccarne i contatti finché non intendi usarlo: in quel momento parte un contatore interno dei giorni, che non si può fermare. La <a href="./../troubleshoot/g6.html#transmitter-warranty">garanzia</a> è valida solo se inizi a usare il trasmettitore entro 5 mesi dalla spedizione, e l&#39;ultimo giorno in cui puoi avviare (o riavviare) un sensore su un trasmettitore G6 è il giorno 99 del trasmettitore.</p></div><h4 id="setup-xdrip" tabindex="-1">Configurare xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurare xDrip {#setup-xdrip}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Dex</p></div><p>Poi verifica le impostazioni qui sotto: la maggior parte corrisponde ai valori predefiniti di xDrip, quindi si tratta di un controllo più che di una nuova configurazione. Il funzionamento di ogni impostazione è descritto nelle pagine <a href="#dexcom-advanced-settings-reference">riferimento delle impostazioni avanzate Dexcom</a>, <a href="./../use/bluetooth.html">Impostazioni Bluetooth</a> e <a href="./../use/misc.html">Altre opzioni</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Impostazioni di debug G5/G6</p></div><div class="admonition xdripitem"><p class="admonition-title">Algoritmo nativo <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Usa l&#39;algoritmo interno del trasmettitore per calcolare i valori di glicemia quando possibile.</p></div><div class="admonition xdripitem"><p class="admonition-title">Riavvia sensore <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Riavvia automaticamente il sensore quando si ferma</p></div><div class="admonition xdripitem"><p class="admonition-title">Riavvio preventivo <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Riavvia preventivamente un sensore prima che la sessione finisca il giorno 6/9 per evitare il tempo di avviamento</p></div><p>Lascia disattivate entrambe le opzioni di riavvio. Riutilizzare lo stesso sensore oltre la sua sessione normale è una tecnica a parte, più rischiosa: leggi <a href="./../troubleshoot/g6.html#restarting-a-sensor-beyond-its-normal-session">Riavviare un sensore</a> prima di prenderla in considerazione.</p><div class="admonition xdripitem"><p class="admonition-title">Vai avanti senza calibrazione <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Continua ad utilizzare i dati anche se non ci sono abbastanza calibrazioni valide (sperimentale!)</p></div><div class="admonition xdripitem"><p class="admonition-title">Minimizza scansioni <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa euristica per minimizzare le scansione bluetooth e risparmiare energia</p></div><div class="admonition xdripitem"><p class="admonition-title">Evita Scansione <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Evitare la scansione il più possibile (riduce ulteriormente il consumo della batteria)</p></div><div class="info custom-block"><p class="custom-block-title">Opzioni di scansione</p><p>Minimizza scansioni ed Evita Scansione fanno risparmiare batteria, ma sono disastrose su alcuni telefoni (Samsung, marche cinesi, ...). Inizia con entrambe disattivate: prova ad attivarle, una alla volta, solo quando la connessione è affidabile.</p></div><div class="admonition xdripitem"><p class="admonition-title">Consenti scollegamento OB1 <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Il collector OB1 può scollegarsi se ritiene che la crittografia sia fallita. Se avete problemi con queste disconnessioni, disabilitate l&#39;opzione. Se invece perdete completamente la connessione, assicuratevi che sia abilitata.</p></div><div class="admonition xdripitem"><p class="admonition-title">Abbinamento Speciale <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Some Samsung devices can have an error where they lose the pairing information. This attempts to work around the issue.</p></div><p>Attiva Abbinamento Speciale sui telefoni Samsung e su alcuni telefoni cinesi.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../use/misc.html">Altre opzioni</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Modalità Sviluppatore <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Consente di cambiare le impostazioni più pericolose: a vostro rischio e pericolo!</p></div><div class="admonition xdripitem"><p class="admonition-title">Richiesta di Ottimizzazione della Batteria <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Con Android 6+ verifica che l&#39;ottimizzazione della batteria sia spenta. Raccomandato</p></div><div class="admonition xdripitem"><p class="admonition-title">Samsung Workaround <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Usa workaround per evitare il comportamento non standard a Android degli telefonini Samsung. Senza questo, di solito non si riesce a ricevere dati.</p></div><div class="admonition xdripitem"><p class="admonition-title">Uso eccessivo Wakelocks <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchi wakelocks gratuiti possono consumare la batteria, ma potrebbero essere necessari per NightWatch o Android Wear</p></div><div class="admonition xdripitem"><p class="admonition-title">Mostra Valori Predetti <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchio metodo - Non consigliato!</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Riavvio servizio aggressivo <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Riavvia ripetutamente il servizio di raccolta in qualsiasi dubbio di dati mancanti. Abilitare solo se si perdono dati.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../calibrate/advancedcal.html">Calibrazione avanzata</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Calibrazione automatica <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Calibra automaticamente utilizzando le letture di glicemia se le condizioni sembrano giuste, senza chiedere conferma (sperimentale)</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  <a href="./../use/lesscommon.html">Impostazioni Meno Usate</a><br>   <a href="./../use/bluetooth.html">Impostazioni Bluetooth</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Attiva Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Attiva automaticamente il bluetooth se è spento quando si prova a connettersi a un dispositivo bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Watchdog Bluetooth <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Resetta Bluetooth (spegni e riaccendi) se non si ricevono dati in 20 minuti</p></div><div class="admonition xdripitem"><p class="admonition-title">Chiusura GATT per scollegamento BLE <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Se il watchdog bluetooth si attiva spesso, provare a deselezionare questa opzione per vedere se aiuta</p></div><div class="admonition xdripitem"><p class="admonition-title">Usa scansione <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Scansiona prima di connettersi a xBridge e Libre Bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><div class="admonition xdripitem"><p class="admonition-title">Trust Auto-Connect <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Usa e confida nella funzione di connessione automatica bluetooth di Android (sconsigliato per miaomiao)</p></div><p>Inizia con Trust Auto-Connect disattivato. Prova ad attivarlo solo se continui a perdere la connessione.</p><div class="admonition xdripitem"><p class="admonition-title">Usa Scansione In Background <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Utilizza la funzione di scansione bluetooth in background Android 8+</p></div><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><div class="admonition xdripitem"><p class="admonition-title">Bluetooth Wakelocks <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Vecchi wakelocks bluetooth (possono necessitare più batteria) che potrebbero essere necessari per la ricezione dei bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">xBridge+ Modalità di Polling <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Supporto sperimentale per la funzione di polling xBridge+</p></div><h4 id="setting-up-for-the-first-time" tabindex="-1">Prima configurazione <a class="header-anchor" href="#setting-up-for-the-first-time" aria-label="Permalink to &quot;Prima configurazione {#setting-up-for-the-first-time}&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Abbi pazienza</p><p>Non affrettarti a toccare &quot;Inizializza Sensore&quot;, anche se xDrip ti invita a farlo. Segui i passaggi qui sotto nell&#39;ordine indicato per evitare i problemi più comuni.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dati Hardware di origine<br>   Dex</p></div><ol><li>Se usi un trasmettitore nuovo, annota il suo numero di serie, stampato sul trasmettitore e sulla scatola. Si attiva non appena lo agganci a un sensore: questo numero ti servirà per un massimo di 110 giorni. Se il numero di serie termina con <code>-1</code>, usa solo i primi sei caratteri.</li><li>Ogni sensore ha un codice di calibrazione a 4 cifre stampato sulla pellicola adesiva: ti servirà per avviare la sessione. Non aprire la confezione del sensore finché non sei pronto a inserirlo, e non buttare via la pellicola adesiva prima di aver annotato il codice.</li><li>Se nella pagina Dex Status c&#39;è un comando bloccato in coda, <a href="./../troubleshoot/g6.html#transmitter-queue-stuck">svuota la coda</a> prima di continuare.</li><li>Se &quot;Inizializza Sensore&quot; non compare tra le opzioni del menu in alto a sinistra, tocca invece &quot;Stop Sensore&quot; e attendi 5 minuti.</li><li>Il trasmettitore deve restare staccato dal corpo per almeno 10 minuti prima di procedere: se lo sposti da un sensore precedente, <a href="./../troubleshoot/g6.html#removing-a-transmitter-without-damaging-the-sensor">rimuoverlo senza danneggiare il sensore</a> spiega come fare.</li><li>Se stai attivando un nuovo trasmettitore, inserisci il suo numero di serie come <a href="#dexcom-transmitter-id">Dexcom trasmettitore ID</a>.</li><li>Pulisci i contatti del trasmettitore con alcol (salta questo passaggio se riavvii lo stesso sensore) e lasciali asciugare per circa 10 secondi. Aggancia il trasmettitore al sensore: è questo che attiva un trasmettitore nuovo.</li><li>Inserisci il sensore seguendo le istruzioni dell&#39;applicatore del produttore. Tieni polvere e sangue lontani dai contatti.</li><li>Tieni d&#39;occhio la pagina Dex Status di <a href="./../troubleshoot/systemstatus.html">Stato del sistema</a>: si aggiorna ogni 5 minuti. Non procedere se la connessione non funziona correttamente: risolvi prima quel problema. Se stai attivando un nuovo trasmettitore, abbi pazienza e attendi che compaiano le tensioni della batteria prima di continuare: può richiedere fino a mezz&#39;ora.</li><li>Tocca Inizializza Sensore e, quando richiesto, inserisci il codice di calibrazione a 4 cifre della pellicola adesiva del sensore. Conserva il codice: potrebbe servirti di nuovo più avanti.</li></ol><div class="warning custom-block"><p class="custom-block-title">Non fare mai il soak di un sensore</p><p>Non fare mai il soak (inserire un sensore un po&#39; di tempo prima di avviarlo in xDrip). La calibrazione di fabbrica è il principale vantaggio di G6/ONE rispetto a G5, e il soak la compromette. Più è lungo l&#39;intervallo tra l&#39;inserimento del sensore e il suo avvio, più ne riduci la precisione.</p></div><p>Le letture iniziano di solito circa 2 ore dopo l&#39;avvio del sensore, senza bisogno di una calibrazione iniziale. Se arrivi da G5 o da un altro CGM, dai una possibilità alla calibrazione di fabbrica: la maggior parte delle persone non ha alcun bisogno di calibrare un sensore G6/ONE, a patto che il codice di calibrazione sia stato inserito correttamente.</p><h4 id="starting-a-subsequent-sensor" tabindex="-1">Avviare un sensore successivo <a class="header-anchor" href="#starting-a-subsequent-sensor" aria-label="Permalink to &quot;Avviare un sensore successivo {#starting-a-subsequent-sensor}&quot;">​</a></h4><p>Quando la sessione di un sensore termina, lo stesso trasmettitore può essere spostato su un nuovo sensore e riutilizzato: fino a circa 11 sensori nel corso della sua vita.</p><ol><li>Tocca Stop Sensore nel menu in alto a sinistra (anche se il sensore si è già fermato e &quot;Inizializza Sensore&quot; non è ancora proposto). Attendi che il comando &quot;stop sensor&quot; lasci la coda nella pagina Dex Status: di solito ci vogliono circa 5 minuti.</li><li><a href="./../troubleshoot/g6.html#removing-a-transmitter-without-damaging-the-sensor">Rimuovi il vecchio trasmettitore senza danneggiare il sensore</a> in cui si trova, così da continuare a usare il sito adesivo del sensore, oppure stacca semplicemente il vecchio sensore se non ti serve più.</li><li>Segui di nuovo <a href="#setting-up-for-the-first-time">Prima configurazione</a> dal passaggio 5 in poi, usando il codice di calibrazione del nuovo sensore.</li></ol><div class="info custom-block"><p class="custom-block-title">Informazioni</p><p>Riutilizzare lo <em>stesso</em> sensore oltre la sua sessione normale, inducendo il trasmettitore a riavviarlo, è una tecnica a parte, più rischiosa, con un rischio reale di letture alte errate: consulta <a href="./../troubleshoot/g6.html#restarting-a-sensor-beyond-its-normal-session">Riavviare un sensore</a> nella risoluzione problemi prima di provarci.</p></div><h4 id="calibration" tabindex="-1">Calibrazione <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibrazione {#calibration}&quot;">​</a></h4><p>Consulta <a href="./../calibrate/101.html">Nozioni di base sulla calibrazione</a> e <a href="./../calibrate/calibrate.html">Calibrare</a> per sapere cos&#39;è la calibrazione e quando farla. Con la normale calibrazione di fabbrica non dovresti aver bisogno di calibrare un sensore G6/ONE: anche il produttore sconsiglia di calibrare troppo spesso.</p><p>Se devi calibrare, tocca &quot;Aggiungere Calibrazione&quot; nel menu in alto a sinistra. Questa voce diventa disponibile solo dopo che sono arrivate almeno 3 letture dall&#39;avvio o dal riavvio del sensore. Calibra solo quando l&#39;andamento è piatto o quasi, e non inserire mai una calibrazione che corregga la lettura attuale di oltre il 20%. Se ti serve una correzione maggiore, distanzia le calibrazioni successive di almeno 25 minuti (45 minuti prima di una terza) invece di farla in un unico grande passo: altrimenti rischi un errore di calibrazione confusa che può bloccare le letture per ore, senza sapere quanto durerà il recupero.</p><h4 id="problems" tabindex="-1">Problemi? <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problemi? {#problems}&quot;">​</a></h4><p>Consulta la pagina <a href="./../troubleshoot/g6.html">risoluzione problemi G6, ONE</a>.</p><br><hr><h3 id="dexcom-advanced-settings-reference" tabindex="-1">Riferimento delle impostazioni avanzate Dexcom <a class="header-anchor" href="#dexcom-advanced-settings-reference" aria-label="Permalink to &quot;Riferimento delle impostazioni avanzate Dexcom {#dexcom-advanced-settings-reference}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dexcom trasmettitore ID<br>  Impostazioni di debug G5/G6</p></div><p>La documentazione di riferimento è <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">qui</a>.</p><br><h4 id="dexcom-transmitter-id" tabindex="-1">Dexcom trasmettitore ID <a class="header-anchor" href="#dexcom-transmitter-id" aria-label="Permalink to &quot;Dexcom trasmettitore ID {#dexcom-transmitter-id}&quot;">​</a></h4><p>Indica a xDrip quale trasmettitore cercare, con quale autenticarsi e a quale associare il traffico BLE in arrivo.</p><p><em>Collector: collector Dexcom e percorsi bridge legati a Dex: Dexcom G5/G6/G7 e alcune configurazioni con bridge Dex</em></p><div class="admonition xdrip"><p class="admonition-title"><img src="'+e+'" style="zoom:75%;"></p><p> Impostazioni<br>  Dexcom trasmettitore ID</p></div><div class="admonition xdripitem"><p class="admonition-title">Dexcom trasmettitore ID</p><p> ID del trasmettitore Dexcom, es.: 12AB3</p></div><p>Inserisci il numero di serie del trasmettitore (solo i primi sei caratteri se termina con <code>-1</code>).</p><h4 id="native-algorithm" tabindex="-1">Algoritmo nativo <a class="header-anchor" href="#native-algorithm" aria-label="Permalink to &quot;Algoritmo nativo {#native-algorithm}&quot;">​</a></h4><p>Usa il percorso di richiesta glucose/eGlucose del trasmettitore stesso, quando supportato, invece del percorso dei dati grezzi del sensore.</p><p><em>Collector: collector Dex OB1 (<code>Ob1G5CollectionService</code>): Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Algoritmo nativo</p></div><h4 id="minimize-scanning" tabindex="-1">Minimizza scansioni <a class="header-anchor" href="#minimize-scanning" aria-label="Permalink to &quot;Minimizza scansioni {#minimize-scanning}&quot;">​</a></h4><p>Riduce la frequenza delle scansioni usando euristiche basate sui tempi e sui dispositivi noti, per risparmiare batteria.</p><p><em>Collector: collector Dex OB1 (<code>Ob1G5CollectionService</code>): Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Minimizza scansioni</p></div><h4 id="avoid-scanning" tabindex="-1">Evita Scansione <a class="header-anchor" href="#avoid-scanning" aria-label="Permalink to &quot;Evita Scansione {#avoid-scanning}&quot;">​</a></h4><p>Riduce ancora di più le scansioni, basandosi maggiormente sui tempi e sull&#39;identità del trasmettitore già noti.</p><p><em>Collector: collector Dex OB1 (<code>Ob1G5CollectionService</code>): Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Evita Scansione</p></div><h4 id="allow-ob1-unbonding" tabindex="-1">Consenti scollegamento OB1 <a class="header-anchor" href="#allow-ob1-unbonding" aria-label="Permalink to &quot;Consenti scollegamento OB1 {#allow-ob1-unbonding}&quot;">​</a></h4><p>Permette a xDrip di rimuovere e ricreare l&#39;abbinamento BLE quando l&#39;abbinamento o la crittografia Dexcom finiscono in uno stato anomalo.</p><p><em>Collector: collector Dex OB1 (<code>Ob1G5CollectionService</code>): Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Consenti scollegamento OB1</p></div><h4 id="special-pairing-workaround" tabindex="-1">Abbinamento Speciale <a class="header-anchor" href="#special-pairing-workaround" aria-label="Permalink to &quot;Abbinamento Speciale {#special-pairing-workaround}&quot;">​</a></h4><p>Modifica la sequenza di abbinamento/connessione OB1 per aggirare problemi di abbinamento specifici di alcuni dispositivi.</p><p><em>Collector: collector Dex OB1 (<code>Ob1G5CollectionService</code>): Dexcom G5/G6/G7, in particolare con modelli di telefono problematici</em></p><div class="admonition xdripitem"><p class="admonition-title">Abbinamento Speciale</p></div><h4 id="manual-slot-number-engineering" tabindex="-1">Manual Slot Number (engineering) <a class="header-anchor" href="#manual-slot-number-engineering" aria-label="Permalink to &quot;Manual Slot Number (engineering) {#manual-slot-number-engineering}&quot;">​</a></h4><p>Forza lo slot di autenticazione usato nel processo di autenticazione Dexcom, per casi di sviluppo/risoluzione problemi.</p><p><em>Collector: collector Dex OB1 (<code>Ob1G5CollectionService</code>): Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Manual Slot Number</p><p> Specify transmitter slot manually, setting this incorrectly will prevent any readings being received.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',104)])])}const f=t(l,[["render",c]]);export{x as __pageData,f as default};
